<script lang="ts">
  /**
   * "Pesquisas de hoje": as nacionais presidenciais do TSE previstas para hoje
   * (ou divulgadas nas últimas 24 h), de qualquer casa, e se já entraram no
   * Radar. Fica colado ao carimbo de última apuração, em todas as páginas.
   * Só lê coverage_monitor.today; não calcula nada.
   */
  import {
    COVERAGE_SECTION_HREF,
    todayBadgeLabel,
    todayPollsOf,
    todayPollsTitle,
    todayRowMeta,
    todayRowStatusText,
    todayTone
  } from '../lib/coverageTypes';
  import { formatDateTime } from '../lib/format';
  import type { OperationsPayload } from '../lib/types';

  export let operations: OperationsPayload;

  $: block = todayPollsOf(operations);
  $: title = block ? todayPollsTitle(block) : '';
  $: stale = block ? title !== 'Pesquisas de hoje' : false;
</script>

{#if block}
  <section class="today-polls" aria-labelledby="today-polls-title" data-testid="today-polls">
    <div class="today-polls-head">
      <strong id="today-polls-title">{title}</strong>
      <span class="today-polls-headline">{block.headline}{stale ? ` · apurado em ${formatDateTime(block.generated_at)}` : ''}</span>
      <a href={COVERAGE_SECTION_HREF} data-route>Ver cobertura →</a>
    </div>
    {#if block.rows.length}
      <ul>
        {#each block.rows as row (row.registration_no)}
          <li class:outside={!row.in_aggregate} data-status={row.status}>
            <span class={`today-badge today-${todayTone(row)}`}>{todayBadgeLabel(row)}</span>
            <strong>{row.house_name}</strong>
            <span class="today-meta">{todayRowMeta(row)}</span>
            <span class="today-status">{todayRowStatusText(row)}</span>
          </li>
        {/each}
      </ul>
    {/if}
  </section>
{/if}

