/**
 * Funções puras do comparativo 2022 × 2026 (/comparativo-2022-2026).
 *
 * Pedido do Douglas em 23/09/2026: "a comparação das pesquisas próximo da
 * eleição comparada com a de 2022, igual a dessa imagem". Tudo aqui só lê
 * cycle_comparison.json (contrato v1): nenhum número é calculado de novo,
 * exceto a conferência margem = Lula − adversário, que é uma checagem do
 * contrato, e o domínio Y comum, que é geometria.
 *
 * Regras que estas funções não podem quebrar:
 *  - valor como a casa publicou (votos totais), uma casa por gráfico;
 *  - 1º e 2º turno nunca se misturam;
 *  - o domínio Y é o mesmo entre 2022 e 2026 NO MESMO TURNO (exceção ao
 *    "eixo começa em zero" do skill grafico-linhas-pesquisa, pedida pelo
 *    Douglas em 23/09/2026 e registrada no skill).
 */
import type {
  CycleComparisonPayload,
  CycleHouse,
  CycleKpiRound,
  CyclePanel,
  CycleProvenanceTier,
  CycleRound,
  CycleTurn,
  CycleYear,
  LabelledSeries,
} from './types';

export const CYCLE_ROUTE = '/comparativo-2022-2026';

/** Par validado do skill grafico-linhas-pesquisa: Lula em tom vermelho, Jair/Flávio em azul. */
export const LULA_COLOR = '#c1652c';
export const RIVAL_COLOR = '#2a78d6';
/** Gráfico "mesma distância": cores por ano (não por candidato, para não confundir com a grade). */
export const YEAR_COLORS: Record<CycleYear, string> = { 2022: '#7c5cc4', 2026: '#121923' };

/** Ordem fixa da grade 2×2: 2022 T1, 2022 T2, 2026 T1, 2026 T2. */
export const PANEL_ORDER: ReadonlyArray<readonly [CycleYear, CycleTurn]> = [
  [2022, 1],
  [2022, 2],
  [2026, 1],
  [2026, 2],
];

const KNOWN_TIERS: ReadonlySet<CycleProvenanceTier> = new Set([
  'historical_corpus',
  'primary_release',
  'contractor_channel',
  'press_verified',
]);

/** Margem Lula − adversário arredondada a 1 casa (a mesma regra do Python). */
export function marginPp(lula: number, rival: number): number {
  const value = Math.round((lula - rival) * 10) / 10;
  return Object.is(value, -0) ? 0 : value;
}

/** "2026-09-23" → "23/09" (o eixo X mostra só dia/mês; o ano está no título do painel). */
export function formatDayMonth(value: string): string {
  return `${value.slice(8, 10)}/${value.slice(5, 7)}`;
}

/** Número do dia (UTC) de uma data ISO, para interpolar marcadores entre colunas. */
export function dayNumber(value: string): number {
  return Date.UTC(Number(value.slice(0, 4)), Number(value.slice(5, 7)) - 1, Number(value.slice(8, 10))) / 86_400_000;
}

/** Os 4 painéis na ordem da grade; um painel ausente vira "indisponível" em vez de sumir. */
export function orderedPanels(house: CycleHouse): CyclePanel[] {
  return PANEL_ORDER.map(([year, turn]) => {
    const found = house.panels.find((panel) => panel.year === year && panel.turn === turn);
    return (
      found ?? {
        year,
        turn,
        election_date: '',
        scenario_kind: turn === 1 ? 'first_round' : year === 2022 ? 'runoff_simulation_pre_t1' : 'runoff_simulation',
        rival_key: year === 2022 ? 'jair_2022' : 'flavio_2026',
        status: 'unavailable',
        reason: 'Painel ausente no contrato publicado.',
        rounds: [],
        reading: null,
      }
    );
  });
}

/** Rodadas em ordem de divulgação (o contrato já ordena; aqui só garante). */
export function sortedRounds(panel: CyclePanel): CycleRound[] {
  return [...panel.rounds].sort((a, b) => a.published_at.localeCompare(b.published_at));
}

export interface DomainOptions {
  /** Passo dos ticks (5 em 5, como a imagem de referência). */
  step?: number;
  /** Fração da altura livre abaixo do menor valor: o rótulo de baixo não pode encostar nas datas. */
  bottomGap?: number;
  /** Fração da altura livre acima do maior valor. */
  topGap?: number;
  floor?: number;
  ceiling?: number;
}

/**
 * Domínio [min, max] em múltiplos de `step` que contém todos os valores e
 * deixa folga proporcional embaixo (rótulo abaixo do ponto + datas do eixo)
 * e em cima (rótulo acima do ponto). null quando não há valor.
 */
export function paddedDomain(values: number[], options: DomainOptions = {}): [number, number] | null {
  const { step = 5, bottomGap = 0.13, topGap = 0.05, floor = 0, ceiling = 100 } = options;
  const finite = values.filter((value) => Number.isFinite(value));
  if (!finite.length || step <= 0) return null;
  const min = Math.min(...finite);
  const max = Math.max(...finite);
  let lo = Math.max(floor, Math.floor(min / step) * step);
  let hi = Math.min(ceiling, Math.ceil(max / step) * step);
  if (hi <= lo) hi = lo + step;
  for (let guard = 0; guard < 100; guard += 1) {
    const span = hi - lo;
    let widened = false;
    if (min - lo < bottomGap * span && lo - step >= floor) {
      lo -= step;
      widened = true;
    }
    if (hi - max < topGap * span && hi + step <= ceiling) {
      hi += step;
      widened = true;
    }
    if (!widened) break;
  }
  return [lo, hi];
}

/**
 * Domínio Y comum aos painéis de 2022 e 2026 do MESMO turno: a mesma
 * distância vertical significa o mesmo número de pontos nos dois anos.
 */
export function sharedYDomain(panels: CyclePanel[], turn: CycleTurn, options: DomainOptions = {}): [number, number] | null {
  const values = panels
    .filter((panel) => panel.turn === turn && panel.status === 'available')
    .flatMap((panel) => panel.rounds.flatMap((round) => [round.lula_pct, round.rival_pct]));
  return paddedDomain(values, options);
}

/**
 * x de um marcador num eixo categórico (uma coluna por data, equiespaçadas):
 * interpola pela data entre as duas colunas vizinhas. `offsetDays` desloca o
 * evento dentro do dia (0,5 = meio-dia: um evento no mesmo dia de uma
 * divulgação fica logo depois dela, porque nenhuma pesquisa divulgada naquele
 * dia teve campo depois do evento). Fora da faixa das colunas → null.
 */
export function markerX(dates: string[], xs: number[], markerDate: string, offsetDays = 0): number | null {
  if (!dates.length || dates.length !== xs.length) return null;
  const target = dayNumber(markerDate) + offsetDays;
  const days = dates.map(dayNumber);
  const first = days[0];
  const last = days[days.length - 1];
  if (target < first || target > last) return null;
  if (days.length === 1) return xs[0];
  for (let index = 0; index < days.length - 1; index += 1) {
    const left = days[index];
    const right = days[index + 1];
    if (target >= left && target <= right) {
      const fraction = right === left ? 0 : (target - left) / (right - left);
      return xs[index] + fraction * (xs[index + 1] - xs[index]);
    }
  }
  return null;
}

/**
 * Onde um evento cai em relação às colunas desenhadas (mesma regra do
 * markerX): 'inside' é desenhado; 'before'/'after' só aparece na nota.
 */
export function markerPlacement(dates: string[], markerDate: string, offsetDays = 0): 'inside' | 'before' | 'after' | 'none' {
  if (!dates.length) return 'none';
  const sorted = [...dates].sort();
  const target = dayNumber(markerDate) + offsetDays;
  if (target < dayNumber(sorted[0])) return 'before';
  if (target > dayNumber(sorted[sorted.length - 1])) return 'after';
  return 'inside';
}

const TIER_SHORT: Record<CycleProvenanceTier, string> = {
  historical_corpus: 'corpus histórico 2022',
  primary_release: 'release da casa',
  contractor_channel: 'veículo contratante',
  press_verified: 'imprensa conferida',
};

export function tierShortLabel(tier: CycleProvenanceTier): string {
  return TIER_SHORT[tier] ?? tier;
}

/** Ordem fixa da legenda de proveniência (do histórico ao descritivo), independente da ordem das chaves no JSON. */
export const TIER_ORDER: readonly CycleProvenanceTier[] = ['historical_corpus', 'primary_release', 'contractor_channel', 'press_verified'];

/**
 * Legenda de um tier sem repetir o rótulo curto que a página já escreve em
 * negrito ("imprensa conferida: Imprensa conferida: …" → "imprensa
 * conferida: números iguais…").
 */
export function tierLegendText(tier: CycleProvenanceTier, text: string): string {
  const short = tierShortLabel(tier).toLocaleLowerCase('pt-BR');
  const match = /^([^:]{1,60}):\s*/.exec(text);
  if (match && match[1].trim().toLocaleLowerCase('pt-BR') === short) {
    const rest = text.slice(match[0].length);
    return rest.charAt(0).toLocaleUpperCase('pt-BR') + rest.slice(1);
  }
  return text;
}

function formatDecimal(value: number): string {
  return new Intl.NumberFormat('pt-BR', { maximumFractionDigits: 1 }).format(value);
}

/** Nota curta de cada rodada (tooltip do gráfico): registro, campo, amostra, margem, cenário e origem. */
export function roundNote(round: CycleRound): string {
  const bits = [round.registration_no ?? 'sem registro'];
  if (round.field_start && round.field_end) bits.push(`campo ${formatDayMonth(round.field_start)}–${formatDayMonth(round.field_end)}`);
  if (round.sample_size) bits.push(`n=${new Intl.NumberFormat('pt-BR').format(round.sample_size)}`);
  if (round.margin_of_error != null) bits.push(`±${formatDecimal(round.margin_of_error)} p.p.`);
  if (round.scenario_note) bits.push(round.scenario_note);
  bits.push(tierShortLabel(round.provenance.tier));
  return bits.join(' · ');
}

/** Duas séries por painel: Lula e o adversário daquele ano (Jair em 2022, Flávio em 2026). */
export function panelSeries(panel: CyclePanel, candidates: CycleComparisonPayload['candidates']): LabelledSeries[] {
  if (panel.status !== 'available' || !panel.rounds.length) return [];
  const rounds = sortedRounds(panel);
  const point = (round: CycleRound, value: number) => ({
    date: round.published_at,
    value,
    note: roundNote(round),
    url: round.provenance.sources[0]?.url ?? null,
  });
  return [
    { key: 'lula', label: candidates.lula?.label ?? 'Lula', color: LULA_COLOR, points: rounds.map((round) => point(round, round.lula_pct)) },
    {
      key: panel.rival_key,
      label: candidates[panel.rival_key]?.label ?? 'Adversário',
      color: RIVAL_COLOR,
      points: rounds.map((round) => point(round, round.rival_pct)),
    },
  ];
}

/**
 * Chave categórica de "dias até o 1º turno" que ordena do mais distante para
 * o mais próximo (o eixo lê da esquerda para a direita rumo à eleição).
 */
const DISTANCE_BASE = 10_000;

export function distanceKey(days: number): string {
  return String(DISTANCE_BASE - days).padStart(5, '0');
}

export function distanceFromKey(key: string): number {
  return DISTANCE_BASE - Number(key);
}

/**
 * "Mesma distância da eleição": margem Lula − adversário por dias até o 1º
 * turno, 2022 e 2026 no mesmo gráfico, um gráfico por turno.
 */
export function sameDistanceSeries(house: CycleHouse, turn: CycleTurn, candidates: CycleComparisonPayload['candidates']): LabelledSeries[] {
  return orderedPanels(house)
    .filter((panel) => panel.turn === turn && panel.status === 'available' && panel.rounds.length)
    .map((panel) => {
      const rival = candidates[panel.rival_key]?.label ?? 'adversário';
      const rivalShort = rival.split(/\s+/)[0] ?? rival;
      return {
        key: `margem-${panel.year}`,
        label: `${panel.year} · Lula − ${rivalShort}`,
        color: YEAR_COLORS[panel.year],
        points: sortedRounds(panel).map((round) => ({
          date: distanceKey(round.days_to_first_round),
          value: round.margin_pp,
          note: `divulgação ${formatDayMonth(round.published_at)}/${panel.year} · ${roundNote(round)}`,
          url: round.provenance.sources[0]?.url ?? null,
        })),
      };
    });
}

/** Tiers de proveniência presentes num painel, na ordem em que aparecem, com a legenda do contrato. */
export function panelTiers(panel: CyclePanel, legend: CycleComparisonPayload['provenance_tiers']): Array<{ tier: CycleProvenanceTier; text: string }> {
  const seen: CycleProvenanceTier[] = [];
  panel.rounds.forEach((round) => {
    if (!seen.includes(round.provenance.tier)) seen.push(round.provenance.tier);
  });
  return seen.map((tier) => ({ tier, text: legend[tier] ?? tier }));
}

/** Texto "a N dias do 1º turno" com singular correto. */
export function daysLabel(days: number): string {
  return `${days} ${Math.abs(days) === 1 ? 'dia' : 'dias'}`;
}

/** Linha "mesma distância" do cartão KPI, ou null quando não há rodada de 2022 comparável. */
export function sameDistanceLine(round: CycleKpiRound | null, formatSigned: (value: number) => string): string | null {
  if (!round) return null;
  return `em 2022, a ${daysLabel(round.days_to_first_round)} do 1º turno, ${formatSigned(round.margin_pp)} p.p.`;
}

/**
 * Conferências do contrato que a UI faz antes de desenhar. Qualquer item
 * aqui vira alerta de "fora do contrato" — nunca um gráfico com número
 * incoerente.
 */
export function contractProblems(payload: unknown): string[] {
  const problems: string[] = [];
  if (!payload || typeof payload !== 'object') return ['payload vazio'];
  const data = payload as Partial<CycleComparisonPayload>;
  if (typeof data.run_id !== 'string') problems.push('run_id ausente');
  if (data.role !== 'descriptive_comparison') problems.push(`role inesperado: ${String(data.role)}`);
  if (data.basis !== 'published_total') problems.push(`base inesperada: ${String(data.basis)}`);
  if (data.date_axis !== 'published_at') problems.push(`eixo de data inesperado: ${String(data.date_axis)}`);
  if (!data.candidates?.lula || !data.candidates?.jair_2022 || !data.candidates?.flavio_2026) problems.push('candidaturas do contrato incompletas');
  if (!data.provenance_tiers) problems.push('legenda de proveniência ausente');
  if (data.generation?.no_causal_language !== true) problems.push('geração sem a garantia no_causal_language');
  if (!Array.isArray(data.houses)) {
    problems.push('houses ausente');
    return problems;
  }
  data.houses.forEach((house) => {
    const id = house?.house_id ?? '?';
    if (!Array.isArray(house?.panels) || house.panels.length !== 4) {
      problems.push(`${id}: esperava 4 painéis`);
      return;
    }
    house.panels.forEach((panel, index) => {
      const [year, turn] = PANEL_ORDER[index];
      if (panel.year !== year || panel.turn !== turn) problems.push(`${id}: painel ${index + 1} fora da ordem (${panel.year} T${panel.turn})`);
      if (panel.status === 'available' && !panel.rounds.length) problems.push(`${id} ${panel.year} T${panel.turn}: disponível sem rodadas`);
      panel.rounds.forEach((round) => {
        if (!KNOWN_TIERS.has(round.provenance?.tier)) problems.push(`${id} ${round.registration_no}: tier desconhecido`);
        if (Math.abs(marginPp(round.lula_pct, round.rival_pct) - round.margin_pp) > 0.051) {
          problems.push(`${id} ${round.registration_no}: margem ${round.margin_pp} ≠ Lula − adversário`);
        }
      });
    });
    if (!Array.isArray(house.kpis)) problems.push(`${id}: kpis ausente`);
    if (!Array.isArray(house.markers)) problems.push(`${id}: markers ausente`);
    if (!Array.isArray(house.insights)) problems.push(`${id}: insights ausente`);
  });
  return problems;
}
